"""Returns the largest palindrome made from the product of two 3-digit
    numbers which is less than n.

    >>> solution(20000)
    19591
    >>> solution(30000)
    29992
    >>> solution(40000)
    39893
    """
def solution(n: Any) -> object {
    answer = 0;
    for i in range(999, 99, -1) {
        for j in range(999, 99, -1) {
            t = str((i * j));
            if ((t == t[::-1]) and ((i * j) < n)) {
                answer = max(answer, (i * j));
            }
        }
    }
    return answer;
}

"""
    Return a surface form of the given question element.
    the output should be properly able to precede a predicate (or blank otherwise)
    """
def normalize_element(elem: Any) -> object {
    return elem.replace("_", " ") if (elem != "_") else "";
}

"""
    replace potentially problematic characters in provided string, a branch name

    e.g. copr says:
        Name must contain only letters, digits, underscores, dashes and dots.
    """
def sanitize_branch_name(branch_name: str) -> str {
    offenders = "!@#$%^&*()+={[}]|\\'\":;<,>/?~`";
    for o in offenders {
        branch_name = branch_name.replace(o, "-");
    }
    return branch_name;
}

""" Calculate the simple gap penalty multiplier for the column. If the
    sequences are weighted, the gaps, when penalized, are weighted
    accordingly. """
def weighted_gap_penalty(col: Any, seq_weights: Any) -> object {
    if (len(seq_weights) != len(col)) {
        seq_weights = [1.0] * len(col);
    }
    gap_sum = 0.0;
    for i in range(len(col)) {
        if (col[i] == '-') {
            gap_sum += seq_weights[i];
        }
    }
    return (1 - (gap_sum / sum(seq_weights)));
}

